import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmInfCurso = () => {
  const { id } = useParams(); // Captura o ID do curso pela URL
  const [curso, setCurso] = useState({
    nome: "",
    nivel: "",
    periodo: "",
    area: "",
    professor: "",
    alunos: [], // Inicializando alunos como um array vazio
  });
  const [alunosSelecionados, setAlunosSelecionados] = useState([]); // Alunos que o admin escolheu
  const [alunosDisponiveis, setAlunosDisponiveis] = useState([]); // Alunos da base de dados (serão filtrados)
  const [alunosBusca, setAlunosBusca] = useState(""); // Termo de busca
  const [professores, setProfessores] = useState([]); // Estado para armazenar lista de professores
  const [editMode, setEditMode] = useState(false); // Controle do modo de edição

  // Função para buscar as informações do curso e professores
  useEffect(() => {
    const fetchCurso = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setCurso(dados);
          setAlunosSelecionados(dados.alunos); // Carregar os alunos que já estão no curso
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    const fetchAlunos = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/alunos`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setAlunosDisponiveis(dados); // Todos os alunos disponíveis
        }
      } catch (error) {
        console.error("Erro na requisição de alunos:", error);
      }
    };

    const fetchProfessores = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/professores`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setProfessores(dados);
        }
      } catch (error) {
        console.error("Erro na requisição de professores:", error);
      }
    };

    fetchCurso();
    fetchAlunos();
    fetchProfessores();
  }, [id]);

  // Função para ativar o modo de edição
  const handleEditClick = () => setEditMode(true);

  // Função para cancelar a edição
  const handleCancelClick = () => setEditMode(false);

  // Função para salvar as edições do curso
  const handleSaveClick = async () => {
    if (!curso) return;

    try {
      const resposta = await fetch(`http://localhost:5000/cursos/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...curso, alunos: alunosSelecionados }),
      });

      if (resposta.ok) {
        setEditMode(false);
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Função para atualizar os dados do curso
  const handleChange = (e) => {
    setCurso({ ...curso, [e.target.name]: e.target.value });
  };

  // Função para atualizar os alunos selecionados
  const handleAlunosSelecionados = (aluno) => {
    if (!alunosSelecionados.includes(aluno)) {
      setAlunosSelecionados([...alunosSelecionados, aluno]);
    }
  };

  // Função para remover um aluno da seleção
  const handleRemoveAluno = (aluno) => {
    setAlunosSelecionados(alunosSelecionados.filter((a) => a !== aluno));
  };

  // Função para pesquisar alunos com base no nome
  const handleBuscaChange = (e) => {
    setAlunosBusca(e.target.value);
  };

  // Filtrando alunos com base na busca
  const alunosFiltrados = alunosDisponiveis.filter((aluno) =>
    aluno.nome.toLowerCase().includes(alunosBusca.toLowerCase())
  );

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistcurso">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistprof">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{curso.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={handleEditClick}>
            Editar
          </button>
        )}
      </div>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        {/* Informação do curso */}
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informações do Curso</h4>
          <p>
            <strong>{curso.nome}</strong>
          </p>
          <p>{curso.nivel}</p>
          <p>{curso.periodo}</p>
          <p>{curso.area}</p>
        </div>

        {/* Formulário de edição */}
        <div className="w-50 ps-4">
          <div className="mb-3">
            <label className="fw-bold">Professor</label>
            <div className="input-group">
              <select
                className="form-control"
                name="professor"
                value={curso.professor}
                onChange={handleChange}
                disabled={!editMode}
              >
                <option value="">Selecione um professor</option>
                {professores.map((professor) => (
                  <option key={professor.id} value={professor.nome}>
                    {professor.nome}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <label className="fw-bold">Adicionar Alunos</label>
          <input
            type="text"
            className="form-control mb-2"
            placeholder="Pesquisar aluno"
            value={alunosBusca}
            onChange={handleBuscaChange}
            disabled={!editMode}
          />
          <ul className="list-group">
            {alunosFiltrados.map((aluno) => (
              <li
                key={aluno.id}
                className="list-group-item d-flex justify-content-between align-items-center"
              >
                {aluno.nome}
                <button
                  className="btn btn-sm btn-primary"
                  onClick={() => handleAlunosSelecionados(aluno.nome)}
                  disabled={!editMode}
                >
                  Adicionar
                </button>
              </li>
            ))}
          </ul>

          <div className="mt-3">
            <h5>Alunos Selecionados</h5>
            <ul className="list-group">
              {alunosSelecionados.map((aluno, index) => (
                <li
                  key={index}
                  className="list-group-item d-flex justify-content-between align-items-center"
                >
                  {aluno}
                  <button
                    className="btn btn-sm btn-danger"
                    onClick={() => handleRemoveAluno(aluno)}
                  >
                    Remover
                  </button>
                </li>
              ))}
            </ul>
          </div>

          {editMode && (
            <div className="d-flex justify-content-between mt-3">
              <button className="btn btn-danger" onClick={handleCancelClick}>
                Cancelar
              </button>
              <button className="btn btn-primary" onClick={handleSaveClick}>
                Salvar
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdmInfCurso;
